begin;
do $$
declare a uuid;b uuid;c uuid;d uuid;room uuid;review uuid:=gen_random_uuid();comment_id uuid;call_id uuid;v jsonb;
begin
 perform set_config('request.jwt.claims','{"iss":"https://securetoken.google.com/mymap-a3ae4","aud":"mymap-a3ae4","sub":"android-social-qa-alice"}',true);a:=public.mm_identity();
 perform set_config('request.jwt.claims','{"iss":"https://securetoken.google.com/mymap-a3ae4","aud":"mymap-a3ae4","sub":"android-social-qa-bob"}',true);b:=public.mm_identity();
 perform set_config('request.jwt.claims','{"iss":"https://securetoken.google.com/mymap-a3ae4","aud":"mymap-a3ae4","sub":"android-social-qa-carol"}',true);c:=public.mm_identity();
 perform set_config('request.jwt.claims','{"iss":"https://securetoken.google.com/mymap-a3ae4","aud":"mymap-a3ae4","sub":"android-social-qa-dave"}',true);d:=public.mm_identity();
 insert into public.vc_connections(requester_id,addressee_id,status) values(a,b,'accepted'),(a,c,'accepted'),(a,d,'accepted');
 perform set_config('request.jwt.claims','{"iss":"https://securetoken.google.com/mymap-a3ae4","aud":"mymap-a3ae4","sub":"android-social-qa-alice"}',true);
 execute 'set local role anon';
 room:=public.mm_create_room('QA group',array[b,c]);
 perform public.mm_group_action(room,'invite',d,'');
 if exists(select 1 from public.mm_rooms where id=room and d=any(members)) then raise exception 'Invitation bypassed consent';end if;
 perform public.mm_social_action('close',b,true);
 if jsonb_array_length(public.mm_social_state()->'closeFriends')<>1 then raise exception 'Close friends absent';end if;
 begin perform public.mm_social_action('follow',b,true);raise exception 'Private profile followed';exception when others then if sqlerrm<>'profile_not_public' then raise;end if;end;
 perform public.mm_doc_save(review,'review','{"name":"QA review","note":"Review body","place":{"name":"QA","latitude":21,"longitude":105},"rating":4,"visitedAt":1791432000000}',0,'{}',null);
 call_id:=public.mm_start_call(room,'video');v:=public.mm_call_authorize(call_id);
 if v->>'identity'<>a::text or v->>'room'<>'mymap-call-'||call_id::text or v->>'mode'<>'video' then raise exception 'Spoofed call grant';end if;
 perform set_config('request.jwt.claims','{"iss":"https://securetoken.google.com/mymap-a3ae4","aud":"mymap-a3ae4","sub":"android-social-qa-dave"}',true);
 if exists(select 1 from public.mm_rooms where id=room) then raise exception 'Invited user read group before consent';end if;
 begin perform public.mm_call_authorize(call_id);raise exception 'Invited user joined call before consent';exception when others then if sqlerrm<>'call_not_allowed' then raise;end if;end;
 perform public.mm_answer_group_invite(room,true);
 if not exists(select 1 from public.mm_rooms where id=room) then raise exception 'Accepted user cannot read group';end if;
 begin perform public.mm_call_authorize(call_id);raise exception 'Old call survived membership change';exception when others then if sqlerrm<>'call_finished' then raise;end if;end;
 begin perform public.mm_group_action(room,'rename',null,'Forged');raise exception 'Member renamed group';exception when others then if sqlerrm<>'owner_only' then raise;end if;end;
 perform public.mm_content_action(review,'comment','Hello');v:=public.mm_content_details(review);comment_id:=(v->'comments'->0->>'id')::uuid;
 if (v->'comments'->0->>'can_delete')::boolean is distinct from true then raise exception 'Own comment cannot delete';end if;
 perform set_config('request.jwt.claims','{"iss":"https://securetoken.google.com/mymap-a3ae4","aud":"mymap-a3ae4","sub":"android-social-qa-bob"}',true);
 v:=public.mm_content_details(review);if (v->'comments'->0->>'can_delete')::boolean is distinct from false then raise exception 'Stranger has comment delete UI right';end if;
 perform public.mm_content_action(review,'delete_comment','',comment_id);
 if jsonb_array_length(public.mm_content_details(review)->'comments')<>1 then raise exception 'Stranger deleted comment';end if;
 perform public.mm_social_action('publish',null,true);
 begin perform public.mm_moderation_queue();raise exception 'User became moderator';exception when others then if sqlerrm<>'moderator_only' then raise;end if;end;
 perform set_config('request.jwt.claims','{"iss":"https://securetoken.google.com/mymap-a3ae4","aud":"mymap-a3ae4","sub":"android-social-qa-alice"}',true);
 perform public.mm_social_action('follow',b,true);
 call_id:=public.mm_start_call(room,'voice');
 perform public.mm_social_action('block',b,true);
 if exists(select 1 from public.vc_list_connections() where user_id=b) then raise exception 'Blocked user in connections';end if;
 begin perform public.mm_call_authorize(call_id);raise exception 'Blocked call survived';exception when others then if sqlerrm<>'call_finished' then raise;end if;end;
 begin perform public.mm_send_message(gen_random_uuid(),room,'text','Forbidden',0);raise exception 'Blocked conversation sent';exception when others then if sqlerrm<>'blocked_conversation' then raise;end if;end;
 perform set_config('request.jwt.claims','{"iss":"https://securetoken.google.com/mymap-a3ae4","aud":"mymap-a3ae4","sub":"android-social-qa-bob"}',true);
 if exists(select 1 from jsonb_array_elements(public.mm_nearby_content('review',21,105)) r where r->>'id'=review::text) then raise exception 'Blocked review discovered through definer';end if;
 if exists(select 1 from public.mm_documents where id=review) then raise exception 'Blocked review readable';end if;
 begin perform public.mm_call_cleanup_jobs();raise exception 'User can invoke service jobs';exception when insufficient_privilege then null;end;
 execute 'reset role';
 if not exists(select 1 from public.mm_calls where id=call_id and ended_at is not null) then raise exception 'Call revocation job not durable';end if;
end $$;
rollback;
select 'PASS: invitation consent, owner-only management, comments ACL, public-follow opt-in, moderation staff ACL, blocked discovery/messages/calls, durable revocation and service-only cleanup' as result;
